<?php namespace App\Http\Controllers;
use App\Patient; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class PatientMergeController extends Controller {public function create(Patient $patient){abort_unless($patient->profile_status==='provisional',422);return view('emergency.merge',compact('patient'));}public function store(Request $r,Patient $patient){$d=$r->validate(['target_patient_id'=>'required|different:source_patient_id|exists:patients,id','matching_evidence'=>'required|in:id_number,birth_date_and_contact,staff_verified_documents','notes'=>'required|string|max:2000']);abort_unless($patient->profile_status==='provisional',422);DB::transaction(function()use($r,$patient,$d){$target=Patient::whereKey($d['target_patient_id'])->lockForUpdate()->firstOrFail();$counts=[];foreach(['medical_records','student_complaints','consultations','dental_referrals','emergency_encounters','medical_certificates'] as $table){$counts[$table]=DB::table($table)->where('patient_id',$patient->id)->update(['patient_id'=>$target->id]);}DB::table('patient_merge_logs')->insert(['source_patient_id'=>$patient->id,'target_patient_id'=>$target->id,'merged_by'=>$r->user()->id,'matching_evidence'=>$d['matching_evidence'],'moved_counts'=>json_encode($counts),'notes'=>$d['notes'],'created_at'=>now(),'updated_at'=>now()]);$patient->update(['profile_status'=>'merged','status'=>'Inactive','updated_by'=>$r->user()->id]);});return redirect()->route('patients.show',$d['target_patient_id'])->with('success','Provisional record merged; all clinical history was retained.');}}
